package com.codequest.app.data

enum class Language(val label: String, val key: String, val fileExtension: String) {
    PYTHON("Python", "python", "py"),
    JAVASCRIPT("JavaScript", "javascript", "js")
}

enum class ExerciseMode { WRITE, ORDER, DEBUG, FILL, PREDICT, PROJECT }

data class Lesson(
    val id: String,
    val language: Language,
    val chapter: String,
    val title: String,
    val explanation: String,
    val example: String,
    val breakdown: String,
    val mistake: String,
    val memory: String,
    val exercise: String,
    val solution: String,
    val mode: ExerciseMode,
    val question: String,
    val answers: List<String>,
    val correctAnswer: Int,
    val quizExplanation: String
)

private data class Seed(
    val chapter: String,
    val title: String,
    val explanation: String,
    val example: String,
    val breakdown: String,
    val exercise: String,
    val solution: String,
    val question: String,
    val answers: List<String>,
    val correct: Int,
    val mistake: String = "Lies die Schreibweise genau: Klammern, Einrückung und Anführungszeichen haben jeweils eine Aufgabe.",
    val mode: ExerciseMode = ExerciseMode.WRITE
)

private fun buildLessons(language: Language, seeds: List<Seed>): List<Lesson> =
    seeds.mapIndexed { index, seed ->
        Lesson(
            id = "${language.key}-$index",
            language = language,
            chapter = seed.chapter,
            title = seed.title,
            explanation = "${seed.explanation}\n\n${seed.breakdown}\n\n" +
                "Lies das Beispiel Zeile für Zeile. Frage dich jeweils: Welche Information ist gerade gespeichert, " +
                "und was soll der Computer als Nächstes tun? Ein Computer errät keine Absicht – er folgt den " +
                "Anweisungen genau in der geschriebenen Reihenfolge.",
            example = seed.example,
            breakdown = seed.breakdown,
            mistake = seed.mistake,
            memory = "Merke: ${seed.title} wird verständlich, wenn du den Code in kleine Schritte zerlegst.",
            exercise = seed.exercise,
            solution = seed.solution,
            mode = seed.mode,
            question = seed.question,
            answers = seed.answers,
            correctAnswer = seed.correct,
            quizExplanation = seed.answers[seed.correct] + " – " + seed.breakdown
        )
    }

