        Seed("Funktionen", "Funktionen mit def", "Eine Funktion ist ein benanntes kleines Programm, das du bei Bedarf aufrufen kannst. def eröffnet die Definition; der eingerückte Block beschreibt, was beim Aufruf passiert. Erst der Aufruf führt die Funktion aus.", "def winke():\n    print(\"Hallo\")\n\nwinke()", "Die Definition merkt sich den Ablauf; winke() startet ihn und zeigt Hallo.", "Definiere gruss(), die Hallo ausgibt, und rufe sie auf.", "def gruss():\n    print(\"Hallo\")\n\ngruss()", "Welches Wort beginnt eine Python-Funktion?", listOf("def", "fun", "function", "make"), 0),
        Seed("Funktionen", "Parameter", "Ein Parameter ist ein benannter Eingabeplatz einer Funktion. Beim Aufruf erhält er einen konkreten Wert, das Argument. So kann dieselbe Funktion unterschiedliche Namen begrüßen.", "def gruss(name):\n    print(\"Hallo \" + name)\n\ngruss(\"Ada\")", "name ist der Parameter; Ada wird beim Aufruf hineingegeben.", "Schreibe verdopple(wert), die wert mal 2 ausgibt.", "def verdopple(wert):\n    print(wert * 2)\n\nverdopple(4)", "Was ist ein Parameter?", listOf("Ein Eingabeplatz einer Funktion", "Eine Schleife", "Ein Kommentar", "Ein Rückgabewert"), 0),
        Seed("Funktionen", "return", "return gibt ein Ergebnis aus der Funktion zurück, damit der aufrufende Code es weiterverwenden kann. print() zeigt etwas nur an; diese Aufgaben sind verschieden.", "def addiere(a, b):\n    return a + b\n\nergebnis = addiere(2, 3)\nprint(ergebnis)", "Die Funktion gibt 5 zurück; die Variable speichert den Wert, und print zeigt ihn.", "Erstelle quadrat(zahl), die zahl mal zahl zurückgibt.", "def quadrat(zahl):\n    return zahl * zahl\n\nprint(quadrat(3))", "Was bewirkt return?", listOf("Gibt ein Ergebnis zurück", "Zeigt immer Text", "Startet eine Schleife", "Erstellt einen Parameter"), 0),
        Seed("Funktionen", "Lokale und globale Variablen", "Eine lokale Variable lebt innerhalb ihrer Funktion. Eine globale Variable steht außerhalb und ist an mehreren Stellen sichtbar. Lokale Namen halten Funktionen übersichtlich und vermeiden, dass Teile des Programms sich ungewollt verändern.", "farbe = \"Blau\"\ndef zeige_farbe():\n    nachricht = \"Hallo\"\n    print(farbe, nachricht)\nzeige_farbe()", "farbe ist global; nachricht entsteht nur beim Funktionsaufruf innerhalb der Funktion.", "Erstelle eine Funktion, die eine lokale Variable gruss speichert und ausgibt.", "def sage_hallo():\n    gruss = \"Hallo\"\n    print(gruss)\nsage_hallo()", "Wo ist eine lokale Variable verfügbar?", listOf("In ihrer Funktion", "Überall automatisch", "Nur in Kommentaren", "Nur in Listen"), 0),
        Seed("Fortgeschrittene Grundlagen", "Fehler verstehen", "Ein Fehler ist eine hilfreiche Nachricht darüber, was Python nicht verstanden hat. Syntaxfehler betreffen die Schreibweise; Laufzeitfehler entstehen bei der Ausführung, etwa beim Teilen durch null. Lies Fehlermeldung und Zeilennummer ruhig von unten nach oben.", "zahl = int(\"abc\")", "int kann aus abc keine Zahl machen und meldet einen ValueError; die Meldung zeigt die betroffene Zeile.", "Schreibe eine fehlerhafte Umwandlung int(\"abc\") und erkläre, dass sie einen ValueError auslöst.", "zahl = int(\"abc\")\nprint(zahl)", "Was hilft beim Finden eines Fehlers?", listOf("Fehlermeldung und Zeilennummer lesen", "Alle Zeilen löschen", "Zufällig Namen ändern", "Internetverbindung einschalten"), 0, mode = ExerciseMode.DEBUG),
        Seed("Fortgeschrittene Grundlagen", "try und except", "try und except fangen einen erwartbaren Fehler ab, damit dein Programm sinnvoll reagieren kann. In try steht der riskante Schritt; except beschreibt, was bei diesem Fehlertyp passieren soll.", "try:\n    alter = int(\"unbekannt\")\nexcept ValueError:\n    print(\"Bitte eine Zahl eingeben\")", "Die Umwandlung schlägt fehl und Python führt den passenden except-Block aus.", "Fange mit try/except einen ValueError bei int(\"x\") ab.", "try:\n    zahl = int(\"x\")\nexcept ValueError:\n    print(\"Keine Zahl\")", "Was gehört in except?", listOf("Die Reaktion auf einen passenden Fehler", "Der normale Schleifenstart", "Ein Kommentar", "Ein Variablenname"), 0),
        Seed("Fortgeschrittene Grundlagen", "Module", "Ein Modul ist eine Datei mit wiederverwendbaren Werkzeugen. import lädt solche Funktionen und Werte, zum Beispiel das Modul random für Zufallszahlen. So musst du nützliche Dinge nicht selbst neu schreiben.", "import math\nprint(math.sqrt(16))", "import math macht das Modul verfügbar; sqrt berechnet die Quadratwurzel und liefert 4.0.", "Importiere math und berechne die Wurzel von 25.", "import math\nprint(math.sqrt(25))", "Was macht import?", listOf("Macht ein Modul verfügbar", "Führt eine Schleife aus", "Speichert einen Text", "Fängt alle Fehler"), 0),
        Seed("Fortgeschrittene Grundlagen", "Klassen und Objekte", "Eine Klasse ist ein Bauplan; ein Objekt ist ein konkretes Ding nach diesem Bauplan. Klassen bündeln passende Daten und Funktionen. __init__ richtet ein neues Objekt ein; self meint dieses konkrete Objekt.", "class Hund:\n    def __init__(self, name):\n        self.name = name\n\nmein_hund = Hund(\"Milo\")\nprint(mein_hund.name)", "Hund ist der Bauplan, mein_hund das Objekt; sein Name Milo wird am Objekt gespeichert.", "Definiere Klasse Buch mit __init__, die titel am Objekt speichert.", "class Buch:\n    def __init__(self, titel):\n        self.titel = titel\n\nmein_buch = Buch(\"Python\")", "Was ist eine Klasse?", listOf("Ein Bauplan für Objekte", "Eine einzelne Zahl", "Ein Fehler", "Eine Schleife"), 0),
        Seed("Fortgeschrittene Grundlagen", "Mini-Projekt: Einkaufshelfer", "Ein kleines Projekt verbindet Variablen, Listen und Schleifen. Ein Einkaufshelfer speichert mehrere Einträge und zeigt sie nacheinander. Teile die Aufgabe in kleine Schritte: Liste erstellen, Eintrag ergänzen, Liste anzeigen.", "einkauf = [\"Brot\", \"Apfel\"]\neinkauf.append(\"Milch\")\nfor artikel in einkauf:\n    print(artikel)", "Die Liste hält alle Waren, append ergänzt Milch und for gibt jede Ware einzeln aus.", "Baue eine Einkaufsliste mit zwei Dingen, füge Wasser hinzu und gib alles aus.", "einkauf = [\"Brot\", \"Apfel\"]\neinkauf.append(\"Wasser\")\nfor artikel in einkauf:\n    print(artikel)", "Welche Bausteine nutzt das Projekt?", listOf("Liste, append und Schleife", "Nur Kommentare", "Nur eine Klasse", "Nur einen Vergleich"), 0, mode = ExerciseMode.PROJECT),
        Seed("Fortgeschrittene Grundlagen", "Mini-Projekt: Zahlenquiz", "Ein Quiz braucht eine Frage, eine gespeicherte Lösung und eine Entscheidung. Mit einer Funktion kannst du die Prüfung wiederverwenden; mit Bedingungen gibst du passendes Feedback.", "antwort = \"Python\"\nif antwort == \"Python\":\n    print(\"Richtig!\")\nelse:\n    print(\"Versuch es noch einmal\")", "Der Vergleich prüft die Antwort; genau ein passender Zweig gibt Rückmeldung.", "Prüfe die Variable antwort auf Ada und gib Richtig oder Weiter üben aus.", "antwort = \"Ada\"\nif antwort == \"Ada\":\n    print(\"Richtig\")\nelse:\n    print(\"Weiter üben\")", "Welcher Baustein wählt die Rückmeldung?", listOf("if/else", "append()", "import", "range()"), 0, mode = ExerciseMode.PROJECT)
    )
)

val javascriptLessons = buildLessons(
    Language.JAVASCRIPT,
    listOf(
        Seed("Grundlagen", "Was ist JavaScript?", "JavaScript ist eine Programmiersprache, die Webseiten und vielen weiteren Anwendungen Verhalten gibt. Ein Klick kann damit ein Menü öffnen oder eine Nachricht anzeigen. Sie läuft in Browsern und auch auf Servern.", "console.log(\"Hallo!\");", "console.log gibt eine Nachricht in der Entwickler-Konsole aus.", "Gib den Text CodeQuest mit console.log aus.", "console.log(\"CodeQuest\");", "Was ist JavaScript?", listOf("Eine Programmiersprache", "Ein Browser", "Ein Datentyp", "Eine Datenbank"), 0),
        Seed("Grundlagen", "Wo wird JavaScript verwendet?", "JavaScript steckt oft in Webseiten: HTML beschreibt den Inhalt, CSS das Aussehen und JavaScript das Verhalten. Auch Apps und Server können JavaScript nutzen. So kann derselbe Sprachkern ganz verschiedene Aufgaben lösen.", "console.log(\"Die Seite ist bereit\");", "Die Zeile schreibt eine Statusmeldung in die Konsole.", "Schreibe eine Konsolenmeldung Seite bereit.", "console.log(\"Seite bereit\");", "Welche Aufgabe passt besonders zu JavaScript im Browser?", listOf("Auf Klicks reagieren", "Den Bildschirm herstellen", "Akku laden", "Tastatur bauen"), 0),
        Seed("Grundlagen", "Dein erstes console.log()", "console.log() zeigt Informationen in der Entwickler-Konsole, nicht direkt als Seitentext. Die Klammern enthalten, was angezeigt werden soll; ein Text steht in Anführungszeichen.", "console.log(\"Hallo Welt\");\nconsole.log(2 + 3);", "Die erste Zeile zeigt Text; die zweite berechnet 5 und zeigt die Zahl.", "Ergänze die Lücke, sodass Hallo in der Konsole erscheint.", "console.log(\"Hallo\");", "Was macht console.log()?", listOf("Schreibt eine Information in die Konsole", "Erstellt eine Webseite", "Speichert eine Datei", "Startet den Browser"), 0, mode = ExerciseMode.FILL),
        Seed("Grundlagen", "Kommentare", "Kommentare erklären Code für Menschen; JavaScript führt ihren Inhalt nicht aus. // kommentiert den Rest einer Zeile. Für mehrere Zeilen gibt es /* ... */.", "// Begrüßung\nconsole.log(\"Hallo\");", "Die erste Zeile ist eine Notiz; die zweite wird ausgeführt.", "Ordne Kommentar und Ausgabe richtig: erst Kommentar, dann console.log.", "/* Startmeldung */\nconsole.log(\"Start\");", "Wie beginnt ein einzeiliger JavaScript-Kommentar?", listOf("//", "#", "--", "**"), 0, mode = ExerciseMode.ORDER),
        Seed("Grundlagen", "JavaScript-Syntax", "Syntax sind die Schreibregeln einer Sprache. JavaScript unterscheidet Groß- und Kleinschreibung: console und Console sind verschiedene Namen. Semikolons beenden viele Anweisungen; geschweifte Klammern fassen Blöcke zusammen.", "if (true) {\n  console.log(\"Los\");\n}", "Die runden Klammern enthalten die Bedingung; geschweifte Klammern umfassen den Block.", "Schreibe einen if-Block, der bei true den Text Los ausgibt.", "if (true) {\n  console.log(\"Los\");\n}", "Sind name und Name in JavaScript immer derselbe Name?", listOf("Nein, Groß-/Kleinschreibung zählt", "Ja, immer", "Nur bei Zahlen", "Nur in Kommentaren"), 0),
        Seed("Variablen", "let", "let erstellt einen veränderbaren Namen für einen Wert. Du kannst später einen neuen Wert zuweisen. Wähle einen Namen, der verrät, was gespeichert wird.", "let punkte = 0;\npunkte = punkte + 10;\nconsole.log(punkte);", "punkte beginnt bei 0, wird um 10 erhöht und danach als 10 angezeigt.", "Lege mit let leben auf 3 fest und erhöhe es um 1.", "let leben = 3;\nleben = leben + 1;\nconsole.log(leben);", "Wann passt let?", listOf("Wenn sich der Wert ändern darf", "Wenn er nie geändert werden soll", "Für Kommentare", "Für Funktionen"), 0),
        Seed("Variablen", "const", "const erstellt einen Namen, dem du keinen neuen Wert zuweisen darfst. Für Werte, die sich nicht ändern sollen, verhindert const versehentliche Änderungen. Bei Objekten kann sich der Inhalt dennoch ändern.", "const sprache = \"JavaScript\";\nconsole.log(sprache);", "sprache wird einmal gebunden und kann nicht mit einem neuen Wert überschrieben werden.", "Erstelle mit const die Variable land mit dem Text Deutschland.", "const land = \"Deutschland\";\nconsole.log(land);", "Was gilt für eine const-Zuweisung?", listOf("Der Name darf nicht neu zugewiesen werden", "Der Wert wird automatisch gelöscht", "Sie erstellt immer ein Array", "Sie macht den Wert zu einer Zahl"), 0),
        Seed("Variablen", "var und warum es anders ist", "var ist die ältere Art, Variablen anzulegen. Anders als let ist var auf Funktion statt auf Block begrenzt, wodurch Namen unerwartet sichtbar sein können. In neuem Code sind let und const meist klarer.", "if (true) {\n  var alt = \"sichtbar\";\n}\nconsole.log(alt);", "var bleibt außerhalb des if-Blocks sichtbar; let wäre auf den Block beschränkt.", "Schreibe eine let-Variable punktestand mit Wert 0.", "let punktestand = 0;\nconsole.log(punktestand);", "Welche Variablen sind für neuen Code meist klarer?", listOf("let und const", "Nur var", "Nur global", "Keine Variablen"), 0),
        Seed("Variablen", "Strings", "Ein String ist Text. Er kann in einfachen oder doppelten Anführungszeichen stehen; Template-Strings nutzen Backticks und können mit \${} Werte einsetzen. Text und Zahl sind unterschiedliche Arten von Werten.", "const name = \"Ada\";\nconsole.log(`Hallo, \${name}!`);", "Der Template-String fügt den Wert der Variable name in die Begrüßung ein.", "Speichere Mia in name und begrüße sie mit einem Template-String.", "const name = \"Mia\";\nconsole.log(`Hallo, \${name}!`);", "Welches Zeichen umschließt einen Template-String?", listOf("Backticks `", "Eckige Klammern", "Doppelpunkt", "Schrägstrich"), 0),
        Seed("Variablen", "Numbers", "JavaScript verwendet den Typ Number für ganze Zahlen und Dezimalzahlen. Anders als Python trennt JavaScript diese Zahlen nicht in Integer und Float. Mit Rechenzeichen kannst du direkt rechnen.", "const preis = 4.5;\nconsole.log(preis * 2);", "4.5 wird verdoppelt; die Ausgabe ist 9.", "Was zeigt console.log(7 + 5) an? Schreibe nur die Ausgabe.", "12", "Welchen Typ nutzt JavaScript für 3 und 3.5?", listOf("Number", "Integer und Float getrennt", "String", "Boolean"), 0, mode = ExerciseMode.PREDICT),
        Seed("Variablen", "Booleans", "Ein Boolean ist entweder true oder false. Solche Werte beschreiben zum Beispiel, ob ein Spiel läuft oder eine Tür offen ist. Anders als in Python schreibt JavaScript diese Werte klein.", "const istOffen = true;\nconsole.log(istOffen);", "Die Variable speichert den Wahrheitswert true und gibt ihn aus.", "Lege istOnline als false an.", "const istOnline = false;\nconsole.log(istOnline);", "Wie schreibt JavaScript den Wahrheitswert wahr?", listOf("true", "True", "\"true\"", "1"), 0),
        Seed("Variablen", "Undefined und Null", "undefined bedeutet, dass für einen Namen noch kein Wert gesetzt wurde. null bedeutet, dass du ausdrücklich „kein Wert“ gespeichert hast. Die beiden sehen ähnlich aus, haben aber verschiedene Bedeutungen.", "let antwort;\nconsole.log(antwort);\nconst auswahl = null;", "antwort ist automatisch undefined; auswahl wurde absichtlich auf null gesetzt.", "Erstelle let ergebnis ohne Wert und gib es aus.", "let ergebnis;\nconsole.log(ergebnis);", "Was bedeutet undefined typischerweise?", listOf("Noch kein Wert zugewiesen", "Eine leere Liste", "Der Text null", "Falsch"), 0),
        Seed("Variablen", "Datentypen", "typeof hilft, den Typ eines Wertes zu untersuchen. Strings, Numbers und Booleans verhalten sich unterschiedlich. Ein Datenwert mit dem richtigen Typ verhindert viele überraschende Ergebnisse.", "console.log(typeof \"Hallo\");\nconsole.log(typeof 42);\nconsole.log(typeof true);", "Die Ausgaben sind string, number und boolean.", "Prüfe mit typeof den Typ des Wertes 12.", "console.log(typeof 12);", "Was liefert typeof 12?", listOf("number", "int", "string", "boolean"), 0),
        Seed("Variablen", "Type Conversion", "Type Conversion wandelt einen Wert in einen anderen Typ um. Number(\"12\") macht eine Zahl aus Zifferntext; String(12) macht Text daraus. Plus kann Zahlen addieren oder Text verbinden – der Typ ist daher wichtig.", "const zahl = Number(\"12\");\nconsole.log(zahl + 3);", "Die Umwandlung liefert die Zahl 12; die Addition ergibt 15.", "Wandle den Text \"8\" mit Number() um und addiere 2.", "const zahl = Number(\"8\");\nconsole.log(zahl + 2);", "Was macht Number(\"12\")?", listOf("Wandelt gültigen Zahlentext in Number um", "Macht ihn zu Boolean", "Löscht den Wert", "Rundet ihn immer"), 0),
        Seed("Bedingungen", "if", "if führt einen Block aus, wenn seine Bedingung true ergibt. Die Bedingung steht in runden Klammern; der Codeblock steht in geschweiften Klammern. So kann ein Programm auf Situationen reagieren.", "const alter = 20;\nif (alter >= 18) {\n  console.log(\"Willkommen\");\n}", "20 ist mindestens 18, deshalb läuft der eingerahmte Block.", "Gib Start aus, wenn punkte größer als 0 sind.", "const punkte = 5;\nif (punkte > 0) {\n  console.log(\"Start\");\n}", "Wann wird der if-Block ausgeführt?", listOf("Wenn die Bedingung wahr ist", "Immer", "Wenn sie falsch ist", "Nur bei Strings"), 0),
        Seed("Bedingungen", "else", "else beschreibt den alternativen Weg, wenn die if-Bedingung false ist. Zusammen bilden sie eine klare Entweder-oder-Entscheidung. Die geschweiften Klammern markieren beide Codeblöcke.", "const regen = false;\nif (regen) {\n  console.log(\"Schirm\");\n} else {\n  console.log(\"Sonne\");\n}", "regen ist false, deshalb wird nur der else-Block ausgeführt.", "Prüfe muede: Bei true Pause, sonst Weiter.", "const muede = false;\nif (muede) {\n  console.log(\"Pause\");\n} else {\n  console.log(\"Weiter\");\n}", "Wann läuft else?", listOf("Wenn die if-Bedingung false ist", "Vor if", "Immer zusätzlich", "Nur in Schleifen"), 0),
        Seed("Bedingungen", "else if", "else if prüft einen weiteren Fall, wenn frühere Bedingungen nicht gepasst haben. Die Reihenfolge zählt: Sobald ein Zweig zutrifft, wird der Rest übersprungen. Allgemeine Fälle sollten deshalb oft am Ende stehen.", "const note = 2;\nif (note === 1) {\n  console.log(\"Top\");\n} else if (note === 2) {\n  console.log(\"Gut\");\n} else {\n  console.log(\"Üben\");\n}", "Die erste Prüfung ist falsch; die zweite passt und gibt Gut aus.", "Ordne if für 1 Gold und else if für 2 Silber.", "const platz = 2;\nif (platz === 1) {\n  console.log(\"Gold\");\n} else if (platz === 2) {\n  console.log(\"Silber\");\n}", "Was prüft else if?", listOf("Einen weiteren Fall", "Eine neue Funktion", "Eine Liste", "Ein Kommentar"), 0, mode = ExerciseMode.ORDER),
        Seed("Bedingungen", "Vergleichsoperatoren", "=== prüft Wert und Typ auf Gleichheit; !== prüft Ungleichheit. <, >, <= und >= vergleichen Zahlen. === ist meist sicherer als ==, weil es keine überraschende Typumwandlung vornimmt.", "const punkte = 10;\nconsole.log(punkte === 10);\nconsole.log(punkte > 5);", "Beide Ausdrücke sind true: Der Wert ist genau 10 und größer als 5.", "Prüfe, ob antwort streng gleich \"Ja\" ist.", "const antwort = \"Ja\";\nconsole.log(antwort === \"Ja\");", "Welcher Operator prüft strikte Gleichheit?", listOf("===", "=", "=>", "!=="), 0, "=== vergleicht Wert und Typ, ohne automatische Umwandlung."),
        Seed("Bedingungen", "Logische Operatoren", "&& bedeutet „und“: beide Bedingungen müssen stimmen. || bedeutet „oder“: eine wahre Bedingung genügt. ! kehrt true und false um. Mit diesen Operatoren beschreibst du mehrere Regeln gemeinsam.", "const alter = 20;\nconst ticket = true;\nconsole.log(alter >= 18 && ticket);", "Zutritt gibt es nur, wenn die Person alt genug ist und ein Ticket besitzt.", "Prüfe, ob temperatur über 0 und unter 30 liegt.", "const temperatur = 20;\nconsole.log(temperatur > 0 && temperatur < 30);", "Wann ist A && B wahr?", listOf("Wenn beide wahr sind", "Wenn eine wahr ist", "Immer", "Wenn beide falsch sind"), 0),
        Seed("Bedingungen", "switch", "switch wählt einen passenden Fall aus einem Wert. case beschreibt einen Fall; break verhindert, dass danach der nächste Fall weiterläuft. default ist der Auffangfall, falls keiner passt.", "const tag = \"Mo\";\nswitch (tag) {\n  case \"Mo\": console.log(\"Start\"); break;\n  default: console.log(\"Pause\");\n}", "Der Wert Mo passt zum ersten case und zeigt Start; break beendet die Auswahl.", "Erstelle switch mit case \"rot\" und default-Ausgabe.", "const farbe = \"rot\";\nswitch (farbe) {\n  case \"rot\": console.log(\"Stopp\"); break;\n  default: console.log(\"Weiter\");\n}", "Wofür ist break in switch nützlich?", listOf("Beendet den passenden Fall", "Erstellt eine Variable", "Vergleicht Zahlen", "Startet den nächsten case"), 0),
        Seed("Schleifen", "for-Schleifen", "Eine for-Schleife bündelt Startwert, Bedingung und Änderung an einem Ort. Sie ist gut, wenn du weißt, wie oft etwas laufen soll. Achte darauf, dass der Zähler sich verändert und die Bedingung irgendwann endet.", "for (let i = 0; i < 3; i++) {\n  console.log(i);\n}", "i startet bei 0, läuft solange i kleiner als 3 ist und wird pro Runde um eins erhöht.", "Gib mit for die Zahlen 0, 1 und 2 aus.", "for (let i = 0; i < 3; i++) {\n  console.log(i);\n}", "Wie viele Male läuft die Schleife?", listOf("3", "2", "4", "Unendlich"), 0),
        Seed("Schleifen", "while-Schleifen", "while wiederholt einen Block, solange die Bedingung wahr bleibt. Du musst den Zustand im Block ändern, damit die Schleife enden kann. Sonst fragt das Programm immer wieder dieselbe wahre Bedingung ab.", "let schritt = 1;\nwhile (schritt <= 2) {\n  console.log(schritt);\n  schritt++;\n}", "Der Zähler steigt von 1 auf 2 und dann auf 3; bei 3 ist die Bedingung falsch.", "Zähle mit while von 1 bis 2 und erhöhe den Wert.", "let zahl = 1;\nwhile (zahl <= 2) {\n  console.log(zahl);\n  zahl++;\n}", "Wann stoppt while?", listOf("Wenn die Bedingung false wird", "Nach console.log", "Nach einem Kommentar", "Nie"), 0),
        Seed("Schleifen", "do while", "do while führt den Block mindestens einmal aus und prüft die Bedingung erst danach. Das ist nützlich, wenn eine Aktion zuerst passieren soll, etwa eine Eingabe anzufragen, bevor entschieden wird, ob es weitergeht.", "let zahl = 1;\ndo {\n  console.log(zahl);\n  zahl++;\n} while (zahl <= 2);", "Der Block läuft zuerst mit 1; danach wird geprüft, ob der nächste Durchlauf erlaubt ist.", "Gib einmal Hallo in einem do-while-Block aus.", "let bereit = false;\ndo {\n  console.log(\"Hallo\");\n} while (bereit);", "Wie oft läuft do while mindestens?", listOf("Einmal", "Nie", "Zweimal", "Unendlich"), 0),
        Seed("Schleifen", "break und continue", "break verlässt die Schleife sofort. continue überspringt den Rest der aktuellen Runde und beginnt die nächste. So kannst du Schleifen stoppen oder einzelne Werte auslassen.", "for (let i = 0; i < 5; i++) {\n  if (i === 2) continue;\n  if (i === 4) break;\n  console.log(i);\n}", "2 wird übersprungen; bei 4 endet die Schleife. Sichtbar sind 0, 1 und 3.", "Überspringe 2 und stoppe bei 4.", "for (let i = 0; i < 5; i++) {\n  if (i === 2) continue;\n  if (i === 4) break;\n  console.log(i);\n}", "Was macht continue?", listOf("Überspringt die aktuelle Runde", "Beendet die ganze Schleife", "Startet das Programm neu", "Fügt ein Element ein"), 0),
        Seed("Schleifen", "for...of", "for...of nimmt bei jedem Durchlauf direkt das nächste Element einer Sammlung. Du brauchst keinen Index, wenn dich nur die Werte interessieren. Das macht Code mit Arrays oft leichter lesbar.", "const tiere = [\"Hund\", \"Katze\"];\nfor (const tier of tiere) {\n  console.log(tier);\n}", "tier ist beim ersten Durchlauf Hund, beim nächsten Katze.", "Gib mit for...of alle Namen in namen aus.", "const namen = [\"Ada\", \"Sam\"];\nfor (const name of namen) {\n  console.log(name);\n}", "Was liefert for...of bei einem Array?", listOf("Das jeweilige Element", "Immer den Index", "Die Array-Länge", "Ein Objekt"), 0),
        Seed("Arrays und Objekte", "Arrays", "Ein Array sammelt Werte in einer geordneten Reihe. Eckige Klammern umschließen die Einträge; Kommas trennen sie. Ein Array kann wachsen und enthält oft Werte ähnlicher Art.", "const farben = [\"Rot\", \"Grün\", \"Blau\"];\nconsole.log(farben);", "farben enthält drei Einträge in ihrer ursprünglichen Reihenfolge.", "Erstelle ein Array mit Brot und Milch.", "const einkauf = [\"Brot\", \"Milch\"];\nconsole.log(einkauf);", "Welche Zeichen umschließen ein Array?", listOf("[]", "{}", "()", "<>"), 0),
        Seed("Arrays und Objekte", "Array-Elemente", "Arrays nummerieren Plätze ab Index 0. array[0] liest das erste Element; array.length gibt die Anzahl zurück. Das letzte Element liegt bei length - 1.", "const farben = [\"Rot\", \"Blau\"];\nconsole.log(farben[0]);\nconsole.log(farben[farben.length - 1]);", "Der erste Zugriff liefert Rot, der zweite Blau.", "Gib das zweite Element von tiere aus.", "const tiere = [\"Hund\", \"Katze\"];\nconsole.log(tiere[1]);", "Welchen Index hat das erste Element?", listOf("0", "1", "-1", "2"), 0),
        Seed("Arrays und Objekte", "push und pop", "push() hängt ein Element ans Ende eines Arrays. pop() entfernt das letzte Element und gibt es zurück. Beide verändern das ursprüngliche Array.", "const farben = [\"Rot\"];\nfarben.push(\"Blau\");\nconst letzte = farben.pop();\nconsole.log(letzte);", "push fügt Blau hinzu; pop nimmt genau dieses letzte Element wieder heraus.", "Füge Tee an getraenke an und entferne das letzte Element mit pop.", "const getraenke = [\"Wasser\"];\ngetraenke.push(\"Tee\");\ngetraenke.pop();", "Was macht push()?", listOf("Fügt hinten ein Element hinzu", "Entfernt das erste Element", "Sortiert Werte", "Prüft einen Typ"), 0),
        Seed("Arrays und Objekte", "Objekte", "Ein Objekt gruppiert zusammengehörige Angaben unter Namen. Eigenschaften bestehen aus Schlüssel und Wert. So passt ein Objekt gut zu einer Person mit Name, Alter und Lieblingsfarbe.", "const person = { name: \"Mia\", alter: 12 };\nconsole.log(person.name);", "person.name liest die Eigenschaft name aus und liefert Mia.", "Erstelle ein spieler-Objekt mit name Ada und level 2.", "const spieler = { name: \"Ada\", level: 2 };\nconsole.log(spieler.name);", "Wie viele Werte speichert ein Objekt typischerweise pro Eigenschaft?", listOf("Schlüssel und passenden Wert", "Nur einen Index", "Nur eine Zahl", "Zwei Arrays"), 0),
        Seed("Arrays und Objekte", "Eigenschaften und Methoden", "Eine Eigenschaft ist ein gespeicherter Wert eines Objekts. Eine Methode ist eine Funktion, die zu einem Objekt gehört. Mit Punkt-Schreibweise liest du beides; Methoden rufst du mit Klammern auf.", "const person = {\n  name: \"Ada\",\n  begruessen() { return `Hallo \${this.name}`; }\n};\nconsole.log(person.begruessen());", "name ist eine Eigenschaft; begruessen ist eine Methode, die das Objekt mit this.name nutzt.", "Erstelle ein Objekt mit titel und einer methode, die den Titel zurückgibt.", "const buch = {\n  titel: \"Code\",\n  zeigeTitel() { return this.titel; }\n};\nconsole.log(buch.zeigeTitel());", "Was unterscheidet eine Methode von einer einfachen Eigenschaft?", listOf("Eine Methode ist eine Funktion am Objekt", "Eine Methode ist immer eine Zahl", "Eine Eigenschaft ist ein Array", "Es gibt keinen Unterschied"), 0),
        Seed("Funktionen", "Funktionen", "Eine Funktion bündelt Anweisungen unter einem Namen, damit du sie wieder aufrufen kannst. Eine Deklaration mit function wird erst ausgeführt, wenn du den Namen mit Klammern aufrufst.", "function winke() {\n  console.log(\"Hallo\");\n}\nwinke();", "Die Definition beschreibt die Aktion; winke() ruft sie auf.", "Definiere und rufe eine Funktion start() auf, die Los ausgibt.", "function start() {\n  console.log(\"Los\");\n}\nstart();", "Was bewirkt ein Funktionsaufruf?", listOf("Führt den Funktionsblock aus", "Erstellt immer ein Array", "Beendet das Programm", "Ändert die Syntax"), 0),
        Seed("Funktionen", "Parameter", "Parameter sind benannte Eingabeplätze einer Funktion. Beim Aufruf übergibst du Argumente, die in diese Plätze gelangen. Dadurch kann eine Funktion mit unterschiedlichen Daten arbeiten.", "function begruesse(name) {\n  console.log(`Hallo \${name}`);\n}\nbegruesse(\"Ada\");", "name ist der Parameter; Ada das Argument, das beim Aufruf eingesetzt wird.", "Schreibe verdopple(wert), die wert mal 2 in der Konsole ausgibt.", "function verdopple(wert) {\n  console.log(wert * 2);\n}\nverdopple(4);", "Was ist ein Argument?", listOf("Ein konkreter Wert beim Funktionsaufruf", "Der Funktionsname", "Ein Kommentar", "Eine Schleife"), 0),
        Seed("Funktionen", "return", "return gibt ein Ergebnis an den Aufrufer zurück. Das Ergebnis kann in einer Variable gespeichert oder weitergerechnet werden. console.log zeigt dagegen nur etwas an; es ersetzt return nicht.", "function addiere(a, b) {\n  return a + b;\n}\nconst ergebnis = addiere(2, 3);\nconsole.log(ergebnis);", "Die Funktion liefert 5; die Variable speichert es und console.log zeigt es.", "Schreibe quadrat(zahl), die zahl mal zahl zurückgibt.", "function quadrat(zahl) {\n  return zahl * zahl;\n}\nconsole.log(quadrat(3));", "Was macht return?", listOf("Liefert ein Ergebnis zurück", "Zeigt automatisch eine Seite", "Erstellt einen Parameter", "Startet eine Schleife"), 0),
        Seed("Funktionen", "Arrow Functions", "Eine Arrow Function ist eine kurze Schreibweise für eine Funktion mit =>. Der Pfeil trennt Eingaben vom Funktionskörper. Bei einem einzigen Ausdruck kann der Wert direkt zurückgegeben werden.", "const addiere = (a, b) => a + b;\nconsole.log(addiere(2, 3));", "a und b sind Eingaben; der Ausdruck rechts vom Pfeil wird als Ergebnis zurückgegeben.", "Schreibe eine Arrow Function doppelt, die eine Zahl mal 2 zurückgibt.", "const doppelt = zahl => zahl * 2;\nconsole.log(doppelt(4));", "Welches Zeichen verbindet Parameter und Funktionskörper?", listOf("=>", "==", "::", "->"), 0),
        Seed("Fortgeschrittene Grundlagen", "Scope", "Scope beschreibt, wo ein Name sichtbar ist. let und const innerhalb geschweifter Klammern gehören zu diesem Block und sind außerhalb nicht verfügbar. Ein klarer Scope schützt vor versehentlichen Namenskonflikten.", "if (true) {\n  const geheim = \"innen\";\n  console.log(geheim);\n}", "geheim ist innerhalb des if-Blocks gültig; außerhalb wäre es nicht definiert.", "Erstelle in einem if-Block eine lokale const nachricht und gib sie dort aus.", "if (true) {\n  const nachricht = \"Hallo\";\n  console.log(nachricht);\n}", "Was beschreibt Scope?", listOf("Wo ein Name sichtbar ist", "Die Größe einer Zahl", "Die Länge eines Arrays", "Eine Ausgabe"), 0),
        Seed("Fortgeschrittene Grundlagen", "Callbacks", "Ein Callback ist eine Funktion, die du einer anderen Funktion übergibst, damit diese sie später aufrufen kann. Das ist praktisch für Ereignisse wie Klicks oder für Aufgaben, die erst später fertig sind.", "function erledigt(callback) {\n  callback();\n}\nerledigt(() => console.log(\"Fertig\"));", "Die Arrow Function wird als Wert übergeben und innerhalb von erledigt aufgerufen.", "Übergib eine Callback-Funktion, die Fertig in die Konsole schreibt.", "function starte(callback) {\n  callback();\n}\nstarte(() => console.log(\"Fertig\"));", "Was ist ein Callback?", listOf("Eine übergebene Funktion für später", "Ein Zahlentyp", "Eine Schleife", "Ein HTML-Element"), 0),
        Seed("Fortgeschrittene Grundlagen", "Promises", "Ein Promise steht für ein Ergebnis, das später verfügbar wird. Es kann noch offen, erfolgreich oder fehlgeschlagen sein. then verarbeitet den Erfolg; catch behandelt einen Fehler.", "Promise.resolve(\"Fertig\")\n  .then(wert => console.log(wert))\n  .catch(fehler => console.log(\"Fehler\"));", "Das Promise ist erfolgreich und then erhält den Wert Fertig.", "Erzeuge mit Promise.resolve den Wert Bereit und gib ihn in then aus.", "Promise.resolve(\"Bereit\")\n  .then(wert => console.log(wert));", "Was beschreibt ein Promise?", listOf("Ein Ergebnis, das später eintrifft", "Eine Schleife", "Ein Objekt ohne Werte", "Eine CSS-Regel"), 0),
        Seed("Fortgeschrittene Grundlagen", "async und await", "async markiert eine Funktion, die ein Promise zurückgibt. await wartet innerhalb dieser Funktion auf das Promise-Ergebnis, ohne die restliche Oberfläche einzufrieren. Fehler können mit try und catch behandelt werden.", "async function ladeName() {\n  const name = await Promise.resolve(\"Ada\");\n  console.log(name);\n}\nladeName();", "await wartet auf den Wert Ada; danach gibt die Funktion ihn aus.", "Schreibe eine async Funktion, die auf Promise.resolve(\"Hallo\") wartet und den Wert ausgibt.", "async function sageHallo() {\n  const text = await Promise.resolve(\"Hallo\");\n  console.log(text);\n}\nsageHallo();", "Wo darf await in der einfachen Standardnutzung stehen?", listOf("In einer async-Funktion", "In jedem Kommentar", "Nur in Arrays", "Nie"), 0),
        Seed("Fortgeschrittene Grundlagen", "DOM-Grundlagen", "Das DOM ist die Baumdarstellung einer Webseite, die JavaScript lesen und verändern kann. document.querySelector findet ein passendes Element; textContent ändert dessen Text. Die Lektion beschreibt Browser-Code, führt ihn hier aber nicht aus.", "const titel = document.querySelector(\"h1\");\ntitel.textContent = \"Hallo!\";", "JavaScript findet die erste h1-Überschrift und ersetzt ihren sichtbaren Text.", "Finde ein Element mit id status und setze seinen textContent auf Bereit.", "const status = document.querySelector(\"#status\");\nstatus.textContent = \"Bereit\";", "Was macht querySelector()?", listOf("Findet ein passendes Element", "Erstellt ein neues Array", "Startet eine Anfrage", "Ändert die Schriftdatei"), 0),
        Seed("Fortgeschrittene Grundlagen", "Mini-Projekt: Einkaufsliste", "Ein kleines Projekt verbindet Arrays und Funktionen. Du kannst Elemente ergänzen und sie mit einer Schleife anzeigen. Teile die Aufgabe auf: Daten speichern, Änderung vornehmen, Ergebnis präsentieren.", "const einkauf = [\"Brot\", \"Apfel\"];\neinkauf.push(\"Milch\");\neinkauf.forEach(artikel => console.log(artikel));", "push fügt Milch hinzu; forEach ruft für jeden Listeneintrag die Ausgabefunktion auf.", "Erstelle eine Liste mit Tee, füge Wasser hinzu und gib alle Einträge aus.", "const einkauf = [\"Tee\"];\neinkauf.push(\"Wasser\");\neinkauf.forEach(artikel => console.log(artikel));", "Welche Funktion ergänzt das Array?", listOf("push()", "pop()", "querySelector()", "typeof"), 0, mode = ExerciseMode.PROJECT),
        Seed("Fortgeschrittene Grundlagen", "Mini-Projekt: Klick-Zähler", "Ein Klick-Zähler kombiniert Zustand und Ereignisse. Eine Variable merkt sich die Anzahl; bei jedem Ereignis wird sie erhöht und angezeigt. In einer echten Webseite würde ein Button das Ereignis auslösen.", "let klicks = 0;\nfunction zaehle() {\n  klicks++;\n  console.log(klicks);\n}\nzaehle();", "klicks startet bei 0; jeder Aufruf von zaehle erhöht den Wert um eins.", "Baue einen Zähler, der bei 0 startet, einmal erhöht wird und den Wert ausgibt.", "let klicks = 0;\nklicks++;\nconsole.log(klicks);", "Welche Schreibweise erhöht eine Zahl um eins?", listOf("klicks++", "klicks--", "klicks == 1", "klicks = null"), 0, mode = ExerciseMode.PROJECT)
    )
)

val allLessons: List<Lesson> = pythonLessons + javascriptLessons

fun lessonsFor(language: Language): List<Lesson> =
    if (language == Language.PYTHON) pythonLessons else javascriptLessons
